package cn.mop.api;
import cn.mop.domain.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class TenantInventoryControllerTest {
    final String actor="58000000-0000-4000-8000-000000000001",tenant="58000000-0000-4000-8000-000000000002";
    PlatformRepository platform;TenantInventoryController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new TenantInventoryController(platform);when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"padmin",7,true)));when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenReturn(List.of());}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/v1/tenants/inventory");r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);r.setAttribute("mop.trace_id","synthetic");return r;}
    Map<?,?> data(MockHttpServletRequest request){return (Map<?,?>)((Map<?,?>)controller.get(request)).get("data");}
    TenantInventory row(int n){return new TenantInventory(String.format("59000000-0000-4000-8000-%012d",n),"合成租户"+n,Instant.EPOCH,n,0,1);}
    @Test void emptyPageKeepsScopeAndMissingFactsExplicit(){var result=data(request());assertEquals(List.of(),result.get("items"));assertEquals(false,result.get("has_more"));assertNull(result.get("next_after_id"));assertEquals(tenant,result.get("context_tenant_id"));assertEquals("ACTIVE_PADMIN_MEMBERSHIPS_ONLY",result.get("scope"));assertEquals(false,result.get("new_tenant_creation_enabled"));verify(platform).authorizedTenantInventory(tenant,actor,7,new TenantInventory.Query(null,16));}
    @Test void boundedLookaheadReturnsFullPageAndActualTailCursor(){var rows=new ArrayList<TenantInventory>();for(int n=1;n<=11;n++)rows.add(row(n));when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenReturn(rows);var r=request();r.addParameter("page_size","10");var result=data(r);assertEquals(10,((List<?>)result.get("items")).size());assertEquals(true,result.get("has_more"));assertEquals(row(10).id(),result.get("next_after_id"));}
    @Test void tailWithoutLookaheadDoesNotAdvertiseAnotherPage(){when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenReturn(List.of(row(1)));var result=data(request());assertEquals(false,result.get("has_more"));assertNull(result.get("next_after_id"));}
    @Test void cursorAndPermissionVersionReachSnapshotRepositoryUnchanged(){var r=request();r.addParameter("after_id",row(1).id());r.addParameter("page_size","100");data(r);verify(platform).authorizedTenantInventory(tenant,actor,7,new TenantInventory.Query(row(1).id(),101));}
    @Test void countsRemainExactDecimalStringsAndNotQuotaOrMonitoring(){var value=TenantInventoryController.projection(new TenantInventory(row(1).id(),"x",Instant.EPOCH,Long.MAX_VALUE,0,1));assertEquals("9223372036854775807",value.get("registered_asset_count"));assertEquals("0",value.get("registered_site_count"));for(String key:List.of("isolation_mode","resource_pool","lifecycle_status","asset_quota","monitored_item_count","item_quota","nvps","nvps_quota","data_retention_days","itsm_integration","topology_enabled")){assertTrue(value.containsKey(key));assertNull(value.get(key));}}
    @Test void nonAdminRolesRejectBeforeReadingInventory(){for(String role:List.of("msp","tadmin","viewer")){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,role,7,true)));assertEquals(403,assertThrows(DomainException.class,()->data(request())).status);}verify(platform,never()).authorizedTenantInventory(anyString(),anyString(),anyLong(),any());}
    @Test void missingPrincipalOrSessionRejectsBeforeRepository(){var a=request();a.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->data(a)).status);var b=new MockHttpServletRequest();b.setUserPrincipal(()->actor);assertEquals(401,assertThrows(DomainException.class,()->data(b)).status);verifyNoInteractions(platform);}
    @Test void malformedOrMissingCurrentTenantRejects(){for(Object value:List.of("bad",42)){var r=request();r.getSession().setAttribute("mop.tenant_id",value);assertEquals(401,assertThrows(DomainException.class,()->data(r)).status);}verifyNoInteractions(platform);}
    @Test void missingInactiveAndInvalidVersionMembershipsReject(){when(platform.membership(actor,tenant)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->data(request())).status);for(var m:List.of(new Membership(actor,tenant,"padmin",7,false),new Membership(actor,tenant,"padmin",0,true))){when(platform.membership(actor,tenant)).thenReturn(Optional.of(m));assertEquals(401,assertThrows(DomainException.class,()->data(request())).status);}verify(platform,never()).authorizedTenantInventory(anyString(),anyString(),anyLong(),any());}
    @Test void unknownScopeOverridesAndDuplicateParametersReject(){for(String key:List.of("tenant_id","role","asset_quota","unknown")){var r=request();r.addParameter(key,"x");assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);}var r=request();r.addParameter("page_size","10","15");assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);}
    @Test void invalidSizeCursorAndOversizeQueryReject(){for(String size:List.of("0","101","15.0"," 15","")){var r=request();r.addParameter("page_size",size);assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);}var r=request();r.addParameter("after_id","' OR true");assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);var large=request();large.setQueryString("x".repeat(513));assertEquals(400,assertThrows(DomainException.class,()->data(large)).status);}
    @Test void repositoryFailureCannotBecomeEmptySuccess(){when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenThrow(new DomainException(503,"UPSTREAM_UNAVAILABLE","redacted"));assertEquals(503,assertThrows(DomainException.class,()->data(request())).status);}
    @Test void staleSnapshotPermissionIsPropagated(){when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenThrow(new DomainException(401,"SESSION_EXPIRED","changed"));assertEquals(401,assertThrows(DomainException.class,()->data(request())).status);}
    @Test void duplicateReversedAndOutOfCursorRowsFailClosed(){for(var rows:List.of(List.of(row(1),row(1)),List.of(row(2),row(1)))){when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenReturn(rows);assertEquals(503,assertThrows(DomainException.class,()->data(request())).status);}when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenReturn(List.of(row(1)));var r=request();r.addParameter("after_id",row(1).id());assertEquals(503,assertThrows(DomainException.class,()->data(r)).status);}
    @Test void overlongRepositoryResultFailsClosed(){when(platform.authorizedTenantInventory(anyString(),anyString(),anyLong(),any())).thenReturn(Collections.nCopies(17,row(1)));assertEquals(503,assertThrows(DomainException.class,()->data(request())).status);}
}
